M.append(dict(id="2.6", go=2, slug="route-and-exit-choice", title="Route and exit choice", minutes=40, tag="Behaviour", systems=["people", "manage"],
 summary="Where people go matters as much as how they walk. Shortest-path, quickest-path and equilibrium rules give different crowd patterns; good guidance moves the crowd towards the best split.",
 outcomes=["compare shortest-path and quickest-path route choice", "find the best split of people between exits", "explain the difference between a user optimum and a system optimum", "describe how information and guidance shift choices"],
 narration_en="Imagine two exits: one near, one far. If everybody takes the nearest, it queues while the far one stands empty. If some take the far exit, they walk longer but wait less, and everyone gets out sooner. The best split equalises the time at which each exit finishes. Models capture this with different rules. The simplest is the shortest path: walk the fewest metres. A better rule is the quickest path: choose the route with the least expected time, walking plus waiting. If everyone chooses selfishly in this way, the crowd reaches a user equilibrium, where no one could do better by switching. The system optimum, best for everyone together, can be different, and may need guidance to reach. In practice, people also follow habit, signs and others, as we saw in Go 1. Simulators compute route choice with distance fields, for example the fast marching method, and update them as congestion grows. In this module you will find the best split between two exits and see how a simple expected-time rule can find it on its own.",
 narration_ar="تخيّل مخرجين: أحدهما قريب والآخر بعيد. إذا اتجه الجميع إلى الأقرب، تكوّن عنده طابور بينما يبقى البعيد فارغاً. وإذا اتجه بعضهم إلى المخرج البعيد، مشوا مسافة أطول لكنهم انتظروا أقل، فيخرج الجميع أسرع. والتقسيم الأفضل يجعل وقت انتهاء كل مخرج متساوياً. وتلتقط النماذج ذلك بقواعد مختلفة. أبسطها أقصر طريق: امشِ أقل عدد من الأمتار. والقاعدة الأفضل أسرع طريق: اختر الطريق ذا الوقت المتوقع الأقل، أي المشي مع الانتظار. وإذا اختار كل شخص بأنانية على هذا النحو، يصل الحشد إلى توازن المستخدم، حيث لا يستطيع أحد أن يحسّن وضعه بالتبديل. أما الأمثل للنظام، أي الأفضل للجميع معاً، فقد يكون مختلفاً، وقد يحتاج إلى توجيه للوصول إليه. وفي الواقع يتبع الناس أيضاً العادة واللافتات والآخرين، كما رأينا في المرحلة الأولى. وتحسب المحاكيات اختيار الطريق بحقول المسافة، كطريقة التقدم السريع، وتحدّثها كلما ازداد الازدحام. ستجد في هذه الوحدة أفضل تقسيم بين مخرجين، وترى كيف تستطيع قاعدة بسيطة للوقت المتوقع أن تجده من تلقاء نفسها.",
 diagram=dict(title="From geometry to choices", caption="Distance fields give the shortest path; adding expected waiting gives the quickest path; guidance nudges the crowd towards the best split.",
   nodes=[N("geo", "Geometry", "walls, exits, routes", 120, 110, "space", "The layout and the possible routes."),
          N("dist", "Distance field", "shortest path", 120, 300, "model", "Distance to each exit, computed with the fast marching method or a graph. Leads everyone to the nearest exit."),
          N("time", "Expected time", "walk + wait", 440, 110, "flow", "Walking time plus expected queuing time, updated as queues grow (quickest path)."),
          N("ue", "User equilibrium", "nobody gains by switching", 440, 300, "people", "Each person picks their quickest route; at equilibrium all used routes take equal time."),
          N("so", "System optimum", "best for all", 760, 300, "manage", "The split that minimises total evacuation time or total delay; may differ from the user equilibrium."),
          N("info", "Guidance", "signs, stewards, apps", 760, 110, "manage", "Dynamic signs, stewards and apps can push choices towards the system optimum."),
          N("hab", "Habit and herding", "real behaviour", 440, 460, "people", "Familiarity, following others and group decisions bias real choices (module 1.6).")],
   edges=[E("geo", "dist"), E("dist", "time", "+ queues"), E("time", "ue", "selfish"), E("ue", "so", "gap?"), E("info", "so", "nudges", "manage"), E("hab", "ue", "biases")],
   tour=[T(["geo", "dist"], "Start from the layout: a distance field gives each person their shortest path.", [["geo", "dist"]]),
         T(["time"], "Add expected waiting time and you get the quickest path.", [["dist", "time"]]),
         T(["ue"], "If everyone chooses their own quickest path, the crowd reaches a user equilibrium.", [["time", "ue"]]),
         T(["so"], "The best split for everyone, the system optimum, can be different.", [["ue", "so"]]),
         T(["info", "hab"], "Guidance nudges people towards it; habit and herding pull the other way.", [["info", "so"], ["hab", "ue"]])]),
 sections=[
  S("Shortest path and distance fields", "<p>The simplest rule: everyone takes the shortest path. In simulators this is a <b>distance field</b>, the distance from every point to the exit, computed for example with the fast marching method, which handles obstacles. People walk down its gradient. With several exits, each person heads for the nearest, which can overload one exit badly.</p>",
    ("Shortest path", "model", "Walk the fewest metres.", [("Distance field", "Distance to the exit everywhere."), ("Fast marching", "Handles obstacles."), ("Overloads", "The nearest exit.")])),
  S("Quickest path and the best split", "<p>Add waiting. A person's expected time to exit k is walking time plus the queue ahead divided by capacity:</p><div class=\"eq\">t<sub>k</sub> = d<sub>k</sub> ÷ v + Q<sub>k</sub> ÷ c<sub>k</sub></div><p>Example: 2,000 people, exit A at 30 m, exit B at 90 m, each passing 4 per s, speed 1.2 m/s. All to A: about 8.8 minutes. Best split: about 45% to B, everyone out in about 5.0 minutes. A simple rule where each person picks the exit with the smaller expected time finds the same split.</p>",
    ("Quickest path", "flow", "Walking plus waiting.", [("t = d/v + Q/c", "Expected time."), ("All to A: 8.8 min", "Nearest exit only."), ("45% to B: 5.0 min", "The best split.")])),
  S("User equilibrium and system optimum", "<p>When everyone minimises their own time, the crowd reaches a <b>user equilibrium</b>: all used routes take the same time and no one gains by switching. The <b>system optimum</b> minimises a total, such as the time until the last person leaves or the sum of everyone's delay. In networks the two can differ (as in Braess's paradox, where adding a route can make everyone slower). Guidance aims to close the gap.</p>",
    ("Equilibrium", "people", "Selfish choices vs the best for all.", [("User equilibrium", "No one gains by switching."), ("System optimum", "Best total."), ("Braess's paradox", "An extra route can hurt.")])),
  S("Guidance in practice", "<p>Real people do not compute expected times. They follow habit, signs, stewards and each other. Guidance that works is <b>early</b>, <b>visible</b> and <b>trusted</b>: dynamic signs showing open exits, stewards redirecting at decision points, and apps or announcements with clear instructions. At mass gatherings, routes are often <b>assigned</b> rather than chosen, by schedule and zone (module 3.3).</p>",
    ("Guidance", "manage", "Early, visible, trusted.", [("Dynamic signs", "Show open exits."), ("Stewards at decision points", "Redirect early."), ("Assigned routes", "Mass gatherings.")])),
 ],
 callouts=[C(1, "try", "Explore it", "<p>In the explorer, find the share that minimises the time. Is it where both exits finish at the same moment?</p>"),
           C(2, "research", "Research angle", "<p>How far real crowds are from the system optimum, and how much guidance can close the gap, is an active research question.</p>")],
 explorer=dict(widget="routechoice", intro="2,000 people, two exits. Choose how many go to the far exit.", predict="Will the best split send more or fewer than half to the far exit?"),
 code=[dict(title="Best split and a quickest-path rule", lang="python", file="labs/go2/m26_route.py", runnable=True, explain="Finds the best split by trying all shares, then lets each person choose the exit with the smaller expected time.", expected="all to the nearest exit: 8.8 min\nbest split: 45% to the far exit, everyone out after 5.0 min\npeople choosing by expected time: 45% to the far exit -> 5.0 min")],
 takeaways=["Shortest-path choice can overload the nearest exit.", "Quickest-path choice adds expected waiting: t = d/v + Q/c.", "User equilibrium (selfish) and system optimum (best for all) can differ.", "Guidance must be early, visible and trusted; mass gatherings often assign routes."],
 quiz=[Q("In the example, sending about 45% to the far exit…", ["Makes everyone slower", "Cuts the time from about 8.8 to 5.0 minutes", "Has no effect", "Doubles the queue"], 1, "Walking further saves waiting."),
       Q("At a user equilibrium…", ["Everyone uses the shortest path", "No one can reduce their own time by switching", "Total time is always minimal", "Nobody moves"], 1, "Used routes take equal time."),
       Q("A distance field gives…", ["The quickest path", "The shortest path", "The density", "The fundamental diagram"], 1, "Distance only, no waiting."),
       Q("Braess's paradox shows that…", ["Adding a route can make everyone slower", "More exits always help", "Signs never work", "Distance does not matter"], 0, "Selfish choices on a new link can raise everyone's time.")],
 glossary=[G("Distance field", "The distance from every point to a target, used to steer simulated people."), G("Fast marching method", "An algorithm to compute distance (or travel-time) fields around obstacles."), G("Quickest path", "The route with the least expected travel time including waiting."), G("User equilibrium", "A state where no one can reduce their own travel time by changing route."), G("System optimum", "The routing that minimises a total measure for everyone.")],
 resources=[RS("Hughes (2002): continuum crowd flow with fastest routes", "https://doi.org/10.1016/S0191-2615(01)00015-7", "Route choice inside a macroscopic model."),
            RS("Haghani and Sarvi (2018): Crowd behaviour and motion, empirical methods", "https://doi.org/10.1016/j.trb.2017.06.017", "Review of experiments including exit choice."),
            RS("Vadere: route choice and floor fields", "https://www.vadere.org/", "Open simulator with distance fields and dynamic routing.")],
 palace=("Signpost bench", "On the sixth bench, a signpost with two arms, NEAR and FAR. A crowd of marbles rolls towards NEAR and jams; a tiny steward flips half of them towards FAR, and both piles empty at the same moment."),
 qb=[("Recall", "What is a quickest-path route choice rule?", "Choose the route with the smallest expected time: walking time plus expected waiting time.", "Time, not distance, is what people care about.", "A satnav that knows about traffic."),
     ("Calculate", "Exit A: 30 m, exit B: 90 m, 4 per s each, 1.2 m/s, 2,000 people, all to A. Time?", "2,000 ÷ 4 = 500 s plus 25 s walking ≈ 525 s ≈ 8.8 min.", "Queue time dominates.", "500 seconds of queuing, 25 of walking."),
     ("Explain", "Why is the best split the one where both exits finish together?", "If one exit finished earlier, moving someone to it from the other would shorten the total; at the optimum no move helps, so finishing times are equal.", "Balance the last person at each exit.", "Two checkout queues should empty together."),
     ("Recall", "Define user equilibrium and system optimum.", "User equilibrium: no one can reduce their own time by switching. System optimum: the routing that minimises a total measure for all.", "Selfish versus collective best.", "Every driver for themselves versus a traffic controller."),
     ("Explain", "What does Braess's paradox teach crowd planners?", "Adding a new route can increase everyone's travel time if people choose selfishly; more connections are not always better.", "Networks can surprise.", "A shortcut that everyone jams."),
     ("Apply", "How would you guide people towards the better exit?", "Early, visible, trusted guidance: dynamic signs showing waiting times or open exits, stewards at decision points, and clear announcements.", "Change information, change choices.", "A sign saying: shorter queue this way.")]))
M.append(dict(id="2.7", go=2, slug="evacuation-modelling", title="Evacuation modelling: RSET and ASET", minutes=45, tag="Safety", systems=["risk", "manage"],
 summary="An evacuation is safe when the time people need (RSET) is less than the time available (ASET), with a margin. Pre-movement time is usually the biggest and most uncertain part.",
 outcomes=["break RSET into detection, warning, pre-movement and movement", "estimate movement time with the hydraulic method", "explain why pre-movement time dominates and is uncertain", "treat RSET as a distribution, not a single number"],
 narration_en="Fire engineers ask a simple question: will everyone get out before conditions become dangerous? The time available, called ASET, comes from fire and smoke modelling. The time required, called RSET, is the sum of four parts: the time to detect the fire, the time to warn people, the pre-movement time while people notice, decide and gather their things or their families, and the movement time to walk to and through the exits. A design is acceptable when RSET is clearly shorter than ASET. Movement time can be estimated by hand with the hydraulic method: the walking time, or the time for the crowd to flow through the exits, whichever is longer. Simulators add detail. But the largest and most uncertain part is usually pre-movement. People finish their conversation, look for friends, or wait for confirmation. Experiments and real evacuations show long, skewed distributions of pre-movement times. That is why careful studies treat RSET not as one number but as a distribution, and look at its high percentiles.",
 narration_ar="يطرح مهندسو الحريق سؤالاً بسيطاً: هل سيخرج الجميع قبل أن تصبح الظروف خطرة؟ والوقت المتاح، ويسمى ASET، يأتي من نمذجة الحريق والدخان. أما الوقت المطلوب، ويسمى RSET، فهو مجموع أربعة أجزاء: زمن اكتشاف الحريق، وزمن تحذير الناس، وزمن ما قبل الحركة الذي يلاحظ فيه الناس ويقررون ويجمعون أغراضهم أو عائلاتهم، وزمن الحركة للمشي إلى المخارج وعبرها. ويكون التصميم مقبولاً عندما يكون RSET أقصر بوضوح من ASET. ويمكن تقدير زمن الحركة يدوياً بالطريقة الهيدروليكية: زمن المشي، أو زمن تدفق الحشد عبر المخارج، أيهما أطول. وتضيف المحاكيات مزيداً من التفاصيل. لكن الجزء الأكبر والأكثر غموضاً هو عادة زمن ما قبل الحركة. فالناس ينهون حديثهم، أو يبحثون عن أصدقائهم، أو ينتظرون التأكيد. وتُظهر التجارب وعمليات الإخلاء الحقيقية توزيعات طويلة ومنحرفة لأزمنة ما قبل الحركة. ولهذا تتعامل الدراسات الدقيقة مع RSET لا كرقم واحد بل كتوزيع، وتنظر إلى نسبه المئوية العليا.",
 diagram=dict(title="RSET against ASET", caption="Four parts add up to the time people need; it must stay below the time conditions allow, with a margin.",
   nodes=[N("det", "Detection", "alarm triggered", 120, 110, "data", "Time from ignition (or an incident) to detection, from detector design or fire modelling."),
          N("warn", "Warning", "people alerted", 340, 110, "manage", "Time to alert people: alarms, voice messages, staff. Voice messages work better than bells."),
          N("pre", "Pre-movement", "notice, decide, gather", 560, 110, "people", "Recognition and response. Often the longest and most variable part; depends on alertness, familiarity, staff and message quality."),
          N("mov", "Movement", "walk and queue", 780, 110, "flow", "Hydraulic estimate: max(walking time, people ÷ exit capacity), or a simulation."),
          N("rset", "RSET", "sum of the four", 450, 300, "risk", "Required safe egress time = detection + warning + pre-movement + movement."),
          N("aset", "ASET", "from fire and smoke", 780, 300, "risk", "Available safe egress time: until smoke, heat or toxicity become untenable, from fire modelling."),
          N("dist", "As a distribution", "percentiles, margin", 450, 450, "data", "Sample uncertain inputs (Monte Carlo) and compare high percentiles of RSET with ASET.")],
   edges=[E("det", "rset"), E("warn", "rset"), E("pre", "rset", "largest"), E("mov", "rset"), E("rset", "aset", "must be <"), E("rset", "dist", "uncertain")],
   tour=[T(["det", "warn"], "First the fire must be detected and people warned.", [["det", "rset"], ["warn", "rset"]]),
         T(["pre"], "Then people notice, decide and gather: pre-movement, often the longest part.", [["pre", "rset"]]),
         T(["mov"], "Then they walk and queue through the exits.", [["mov", "rset"]]),
         T(["rset", "aset"], "The four add up to RSET, which must stay below ASET with a margin.", [["rset", "aset"]]),
         T(["dist"], "Because the inputs are uncertain, treat RSET as a distribution.", [["rset", "dist"]])]),
 sections=[
  S("Two clocks", "<p>Performance-based fire engineering compares two times. <b>ASET</b>, the available safe egress time, runs until smoke, heat or toxic gases make conditions untenable; it comes from fire modelling. <b>RSET</b>, the required safe egress time, is how long people need:</p><div class=\"eq\">RSET = t<sub>detection</sub> + t<sub>warning</sub> + t<sub>pre-movement</sub> + t<sub>movement</sub></div><p>The design is acceptable if RSET &lt; ASET with an adequate safety margin (see the SFPE Handbook and PD 7974-6).</p>",
    ("Two clocks", "risk", "RSET must beat ASET.", [("ASET", "From fire modelling."), ("RSET", "Four parts added."), ("Margin", "RSET clearly below ASET.")])),
  S("Movement time by hand", "<p>The <b>hydraulic method</b> takes the longer of walking time and flow time:</p><div class=\"eq\">t<sub>movement</sub> ≈ max( distance ÷ speed, people ÷ (specific flow × exit width) )</div><p>Example: 1,500 people, 6 m of exits at 1.3 per m per s, 60 m at 1.2 m/s: walking 50 s, flow 1,500 ÷ 7.8 ≈ 192 s, so movement ≈ 192 s. With detection 60 s, warning 30 s and pre-movement 120 s, RSET ≈ 402 s, about 6.7 minutes.</p>",
    ("Hydraulic", "flow", "Walking or queuing, whichever is longer.", [("Walk 60 m at 1.2 m/s", "50 s."), ("1,500 ÷ (1.3 × 6)", "About 192 s."), ("RSET ≈ 402 s", "With 210 s before moving.")])),
  S("Pre-movement time", "<p>People rarely move the moment an alarm sounds. They look for information, finish tasks, find their group. Measured pre-movement times are often <b>long-tailed</b>: most people start within a minute or two, some much later. Pre-movement depends on alertness (asleep or awake), familiarity, staff behaviour and the alarm: <b>voice messages</b> that say what to do shorten it compared with bells.</p>",
    ("Pre-movement", "people", "The biggest, most uncertain part.", [("Long tail", "A few start very late."), ("Depends on", "Alertness, familiarity, staff."), ("Voice messages", "Shorter than bells.")])),
  S("RSET as a distribution", "<p>Uncertain inputs make RSET uncertain. Sample them many times (Monte Carlo): in the lab, a lognormal pre-movement around 120 s and uncertain flow and speed give RSET percentiles of about 323 s (5th), 409 s (50th) and 569 s (95th). Compare a high percentile, not the average, with ASET, and report how sensitive the result is to each input.</p>",
    ("Distribution", "data", "Percentiles, not one number.", [("Monte Carlo", "Sample the inputs."), ("5th / 50th / 95th", "About 323 / 409 / 569 s."), ("Use a high percentile", "Against ASET.")])),
 ],
 callouts=[C(1, "try", "Explore it", "<p>In the explorer, double the pre-movement time. Then double the exit width instead. Which changes RSET more?</p>"),
           C(2, "trap", "Zero pre-movement", "<p>Simulations that start everyone moving at time zero can underestimate RSET badly. Always add a realistic pre-movement distribution.</p>")],
 explorer=dict(widget="rset", intro="Set each part of RSET and the ASET from fire modelling.", predict="Which usually changes RSET more: pre-movement time or exit width?"),
 code=[dict(title="RSET and its uncertainty", lang="python", file="labs/go2/m27_rset.py", runnable=True, explain="A deterministic hydraulic RSET, then 5,000 Monte Carlo samples of uncertain pre-movement, flow and speed.", expected="deterministic RSET: 402 s\nRSET 5th / 50th / 95th percentile: 323 / 409 / 569 s; ASET 900 s\nshare of runs with RSET > ASET: 0.0%")],
 takeaways=["RSET = detection + warning + pre-movement + movement; it must be below ASET with a margin.", "The hydraulic method takes the longer of walking time and flow time.", "Pre-movement time is often the largest and most uncertain part.", "Treat RSET as a distribution and compare high percentiles with ASET."],
 quiz=[Q("RSET stands for…", ["Required safe egress time", "Rapid safe exit test", "Real smoke escape time", "Route safety estimate"], 0, "The time people need."),
       Q("1,500 people, 6 m of exits at 1.3 per m per s. Flow time?", ["About 50 s", "About 192 s", "About 1,170 s", "About 7.8 s"], 1, "1,500 ÷ 7.8 ≈ 192 s."),
       Q("Which part of RSET is usually most uncertain?", ["Detection", "Warning", "Pre-movement", "Walking speed"], 2, "Human response varies widely."),
       Q("Why compare a high percentile of RSET with ASET?", ["Averages hide the slow cases that matter for safety", "It is easier", "ASET is a percentile", "To reduce RSET"], 0, "Safety depends on the tail.")],
 glossary=[G("RSET", "Required safe egress time: detection + warning + pre-movement + movement."), G("ASET", "Available safe egress time, until conditions become untenable."), G("Pre-movement time", "Time from warning to the start of purposeful movement."), G("Hydraulic method", "Movement time from flow rates and walking speeds."), G("Monte Carlo", "Repeated random sampling of uncertain inputs to get a distribution of results.")],
 resources=[RS("SFPE Handbook of Fire Protection Engineering", "https://link.springer.com/referencework/10.1007/978-1-4939-2565-0", "Reference for egress calculations and human behaviour in fire."),
            RS("Ronchi et al. (2013): Verification and validation of evacuation models (NIST TN 1822)", "https://nvlpubs.nist.gov/nistpubs/TechnicalNotes/NIST.TN.1822.pdf", "How to test evacuation models."),
            RS("Kuligowski: The process of human behavior in fires (NIST TN 1632)", "https://nvlpubs.nist.gov/nistpubs/TechnicalNotes/NIST.TN.1632.pdf", "Why people delay before evacuating.")],
 palace=("Clock bench", "On the seventh bench, two big clocks race. ASET's clock is wrapped in smoke; RSET's clock has four hands, and one fat hand labelled PRE-MOVEMENT sometimes stops to look for its friends."),
 qb=[("Recall", "List the four parts of RSET.", "Detection, warning, pre-movement and movement time.", "Something must be noticed, announced, acted on and walked.", "A smoke alarm, a loudspeaker, a person putting on a coat, and a pair of running shoes."),
     ("Calculate", "Detection 60 s, warning 30 s, pre-movement 120 s, movement 192 s. RSET?", "60 + 30 + 120 + 192 = 402 s ≈ 6.7 min.", "Simply add the parts.", "Four coins in a jar."),
     ("Explain", "Why is pre-movement time often the largest uncertainty?", "It depends on human recognition and response (alertness, familiarity, staff, the alarm message, groups), which vary widely and give long-tailed distributions.", "Humans, not physics, set it.", "Waiting for everyone to find their shoes."),
     ("Calculate", "Movement: 60 m at 1.2 m/s, or 1,500 people through 6 m at 1.3 per m per s. Which applies?", "Walking 50 s, flow about 192 s, so movement ≈ 192 s (the longer).", "The slower process limits.", "A short walk to a long queue."),
     ("Explain", "Why treat RSET as a distribution?", "Inputs such as pre-movement, speeds and flows are uncertain; sampling them shows the range of outcomes, and safety depends on the slow tail.", "Plan for the bad day, not the average day.", "Weather forecasts give ranges, not one temperature."),
     ("Apply", "How could you shorten RSET without widening exits?", "Faster detection, clearer voice warnings with instructions, trained staff who start the evacuation, which all reduce pre-movement time.", "Attack the biggest part.", "A clear voice saying: leave now by the left exit.")]))
M.append(dict(id="2.8", go=2, slug="calibration-and-validation", title="Calibration, validation and uncertainty", minutes=45, tag="Method", systems=["data", "flow"],
 summary="A model is only as trustworthy as the data it was tested against. Calibrate parameters on one data set, validate on another, test standard cases, and report the uncertainty.",
 outcomes=["distinguish verification, calibration and validation", "calibrate a fundamental diagram by least squares", "use standard test cases such as the RiMEA tests", "report model uncertainty honestly"],
 narration_en="Every crowd model has parameters: desired speeds, repulsion strengths, floor-field weights. Calibration is choosing their values so that the model matches measurements. Validation is checking the calibrated model against different data it has not seen. Verification comes first and is simpler: does the code do what the equations say? A good calibration uses several observables at once, for example the fundamental diagram, the flow through a bottleneck and travel times, because a model can match one and miss the others. Keep part of the data aside for validation, or the model may only have memorised the data. Standard test cases, such as the RiMEA guideline tests from Germany and the NIST verification tests, check that a simulator behaves sensibly in simple situations: walking speed in a corridor, flow through a door, reaction times. Finally, report uncertainty. Run the model with plausible ranges of parameters and with more than one model if you can, and show how much the answer changes. In this module you will calibrate a fundamental diagram by hand and by computer, and validate it on held-out data.",
 narration_ar="لكل نموذج حشد معاملات: سرعات مرغوبة، وقوى تنافر، وأوزان لحقول الأرضية. والمعايرة هي اختيار قيمها بحيث يطابق النموذج القياسات. والتحقق من الصلاحية هو فحص النموذج المعاير على بيانات مختلفة لم يرها. ويأتي التحقق البرمجي أولاً وهو أبسط: هل يفعل البرنامج ما تقوله المعادلات؟ والمعايرة الجيدة تستخدم عدة مخرجات مقيسة في آن واحد، كالمخطط الأساسي والتدفق عبر عنق الزجاجة وأزمنة الرحلة، لأن النموذج قد يطابق أحدها ويخطئ الأخرى. واحتفظ بجزء من البيانات للتحقق من الصلاحية، وإلا فقد يكون النموذج قد حفظ البيانات فقط. وتتحقق حالات الاختبار القياسية، مثل اختبارات دليل RiMEA الألماني واختبارات المعهد الوطني للمعايير والتقنية الأمريكي، من أن المحاكي يتصرف بشكل معقول في مواقف بسيطة: سرعة المشي في ممر، والتدفق عبر باب، وأزمنة الاستجابة. وأخيراً، أبلغ عن عدم اليقين. شغّل النموذج بنطاقات معقولة من المعاملات وبأكثر من نموذج إن استطعت، وبيّن كم تتغير الإجابة. ستعاير في هذه الوحدة مخططاً أساسياً يدوياً وبالحاسوب، وتتحقق منه على بيانات محجوزة.",
 diagram=dict(title="From code to a trustworthy model", caption="Verify the code, calibrate on one data set, validate on another, then quantify uncertainty.",
   nodes=[N("ver", "Verification", "does the code match the equations?", 130, 110, "model", "Unit tests and simple analytic cases: a single person walks at v₀, nobody passes through walls."),
          N("data", "Data", "FD, bottleneck flow, travel times", 130, 300, "data", "Experiments (Jülich archive), field counts, video. Split into calibration and validation sets."),
          N("cal", "Calibration", "fit parameters", 450, 210, "data", "Choose parameters that minimise an error such as RMSE across several observables."),
          N("val", "Validation", "test on unseen data", 760, 210, "data", "Run the calibrated model on new scenarios or held-out data and compare."),
          N("std", "Standard tests", "RiMEA, NIST", 450, 420, "manage", "Benchmark scenarios that any evacuation simulator should pass."),
          N("unc", "Uncertainty", "ranges, ensembles", 760, 420, "risk", "Parameter ranges, several models, stochastic repeats; report spread and percentiles.")],
   edges=[E("ver", "cal", "first"), E("data", "cal", "calibration set"), E("cal", "val"), E("data", "val", "validation set"), E("std", "val", "also"), E("val", "unc", "then")],
   tour=[T(["ver"], "First verify: the code does what the equations say."),
         T(["data", "cal"], "Then calibrate parameters on part of the data, using several observables.", [["data", "cal"], ["ver", "cal"]]),
         T(["val"], "Validate on data the model has not seen.", [["cal", "val"], ["data", "val"]]),
         T(["std"], "Pass standard test cases too.", [["std", "val"]]),
         T(["unc"], "Finally, quantify and report uncertainty.", [["val", "unc"]])]),
 sections=[
  S("Three different checks", "<p><b>Verification</b>: is the code right? (A lone person walks at v<sub>0</sub>; people never pass through walls.) <b>Calibration</b>: which parameter values make the model match data? <b>Validation</b>: does the calibrated model predict data it was not fitted to? Mixing them up is a common error; a perfectly calibrated but unvalidated model may simply have memorised its data.</p>",
    ("Three checks", "model", "Verify, calibrate, validate.", [("Verification", "Code matches equations."), ("Calibration", "Fit parameters."), ("Validation", "Predict unseen data.")])),
  S("Calibrating a fundamental diagram", "<p>Pick an error measure, often the root mean square error:</p><div class=\"eq\">RMSE = √( (1/n) Σ (v<sub>model</sub>(ρ<sub>i</sub>) − v<sub>i</sub>)² )</div><p>and search for parameters that minimise it. In the lab, 40 'measured' points from a slower crowd give v<sub>0</sub> = 1.08 m/s, γ = 1.60 and ρ<sub>max</sub> = 6.4 per m², with RMSE 0.055 m/s; on 20 held-out points the RMSE is 0.063. Weidmann's default curve gives 0.174: imported parameters can be badly wrong.</p>",
    ("Calibrate", "data", "Minimise the error.", [("RMSE", "Average size of the misfit."), ("Fitted: v₀ 1.08, γ 1.60", "Training RMSE 0.055."), ("Held out: 0.063", "Weidmann default: 0.174.")])),
  S("Several observables and standard tests", "<p>A model fitted only to the fundamental diagram can still get bottleneck flows or travel times wrong (recall the CA in module 2.3). Calibrate on several observables. Then run <b>standard tests</b>: the German <b>RiMEA</b> guideline tests and the NIST verification and validation tests (Ronchi et al. 2013) check simple behaviours that every simulator should get right.</p>",
    ("Many observables", "manage", "Fit more than one thing.", [("FD, bottleneck, travel time", "Calibrate together."), ("RiMEA tests", "German guideline."), ("NIST TN 1822", "V&V tests.")])),
  S("Reporting uncertainty", "<p>Results depend on parameters, random seeds and model choice. Report: the parameter ranges tried, results from repeated stochastic runs (mean and spread), and, where possible, results from a second model. State what the model cannot represent (pushing, groups, information) and how that could bias the answer.</p>",
    ("Uncertainty", "risk", "Ranges, repeats, rival models.", [("Parameter ranges", "Sensitivity."), ("Repeated runs", "Stochastic spread."), ("Second model", "Model uncertainty.")])),
 ],
 callouts=[C(1, "try", "Calibrate by hand", "<p>In the explorer, get the RMSE below 0.06 m/s. Which slider matters most at high density?</p>"),
           C(3, "trap", "Overfitting", "<p>With enough parameters, a model can fit any one data set. Always validate on data you did not use for fitting.</p>")],
 explorer=dict(widget="calibrate", intro="Fit Weidmann's curve to 'measured' speeds from a slower crowd.", predict="Will Weidmann's default parameters fit these data well?"),
 code=[dict(title="Least-squares calibration with validation", lang="python", file="labs/go2/m28_calibrate.py", runnable=True, explain="Grid search over three parameters on 40 training points, then validation on 20 held-out points.", expected="fitted v0 = 1.08 m/s, gamma = 1.60, rho_max = 6.4 per m2, training RMSE 0.055 m/s\nvalidation RMSE 0.063 m/s\nWeidmann's default curve on the same data: RMSE 0.174 m/s")],
 takeaways=["Verification checks code; calibration fits parameters; validation tests on unseen data.", "Calibrate on several observables, not just one.", "Standard tests (RiMEA, NIST) check basic simulator behaviour.", "Report parameter, stochastic and model uncertainty."],
 quiz=[Q("Validation means…", ["Checking the code", "Fitting parameters", "Testing the calibrated model on data it was not fitted to", "Making nice plots"], 2, "Unseen data."),
       Q("Why keep some data aside?", ["To save time", "To test for overfitting", "Because of privacy", "To make the RMSE smaller"], 1, "Held-out data reveal overfitting."),
       Q("Weidmann's default curve on the lab's data gave an RMSE of about…", ["0.055", "0.063", "0.174", "1.34"], 2, "Imported parameters can be badly wrong."),
       Q("RiMEA tests are…", ["Fire tests", "Standard scenarios that evacuation simulators should pass", "Medical tests", "Crowd counting methods"], 1, "A German guideline.")],
 glossary=[G("Verification", "Checking that a model's code correctly implements its equations."), G("Calibration", "Choosing parameter values so a model matches measured data."), G("Validation", "Testing a calibrated model against independent data."), G("RMSE", "Root mean square error, a measure of average misfit."), G("Overfitting", "Fitting noise in one data set so the model predicts new data poorly."), G("RiMEA", "German guideline with standard test cases for evacuation simulators.")],
 resources=[RS("Ronchi et al. (2013): The process of verification and validation of building fire evacuation models (NIST TN 1822)", "https://nvlpubs.nist.gov/nistpubs/TechnicalNotes/NIST.TN.1822.pdf", "Verification and validation tests."),
            RS("RiMEA guideline", "https://rimea.de/", "German guideline for microscopic evacuation analysis, with test cases."),
            RS("Jülich data archive", "https://ped.fz-juelich.de/da/", "Data for calibration and validation.")],
 palace=("Test bench", "On the last bench, a tailor fits a suit on one mannequin (calibration), then tries it on its twin hidden behind a curtain (validation), while a referee holds up a RiMEA scorecard."),
 qb=[("Recall", "Distinguish verification, calibration and validation.", "Verification: code implements the equations. Calibration: fit parameters to data. Validation: test the calibrated model on independent data.", "Right code, right parameters, right predictions.", "Check the oven works, set the temperature, taste a new cake."),
     ("Explain", "Why calibrate on several observables at once?", "A model can match one quantity (such as the fundamental diagram) while getting others (bottleneck flow, travel times) wrong; several targets constrain the parameters better.", "One target leaves too much freedom.", "A suit that fits the shoulders but not the sleeves."),
     ("Calculate", "Model speeds 1.0, 0.8, 0.5; measured 1.1, 0.7, 0.5. RMSE?", "Errors −0.1, 0.1, 0; RMSE = √((0.01 + 0.01 + 0)/3) ≈ 0.082 m/s.", "Square, average, root.", "The typical size of a miss."),
     ("Explain", "What is overfitting and how do you detect it?", "Fitting noise in the calibration data so well that predictions on new data are poor; detect it by validating on held-out data.", "Memorising is not understanding.", "A student who learned last year's exam answers."),
     ("Recall", "Name two sources of standard tests for evacuation simulators.", "The German RiMEA guideline and the NIST verification and validation tests (TN 1822).", "Benchmarks every simulator should pass.", "A driving test for simulators."),
     ("Apply", "What would you report about uncertainty in a simulation study?", "Parameter ranges and sensitivity, spread across repeated stochastic runs, results from a second model if possible, and what the model cannot represent.", "Be honest about the error bars.", "A forecast with a range, not one number.")]))
